/* eslint-disable max-len */
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { CourseService } from 'src/app/data/service/course/course.service';
import { CourseFilterModel, ICourseFilterModel } from '../../../../../data/model/course/CourseFilterModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { ICourseModel } from '../../../../../data/model/course/CourseModel';
import { ExamQuestionFilter, ExamQuestionViewModel, IExamQuestionFilter, QuestionAnswerViewModel, ExamQuestionTestAnswerViewModel, IExamQuestionTestAnswerViewModel, IExamFilter, ExamFilter, ICourseExamViewModel, ICourseExamDetailViewModel } from '../../../../../data/model/course/ExamModel';
import { DatePipe } from '@angular/common';

@Component({
  selector: 'app-exam',
  templateUrl: './exam.component.html',
  styleUrls: ['./exam.component.scss']
})
export class ExamComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;
  queryText = '';
  showSearchbar = false;
  segmentSelected = 'Add';
  windowWidth = 1000;
  filteredCourses: ICourseFilterModel = new CourseFilterModel(false, 1, 20, '');
  examQuestionsFilter: IExamQuestionFilter;
  examsFilter: IExamFilter;
  courseSearch = '';
  isCourseSelected = false;
  selectedCourseId = 0;
  selectedQuestionIndex = -1;
  course: ICourseModel;
  notfound = false;
  updateForm: FormGroup;
  addForm: FormGroup;
  isExamQuestionSelected = false;
  isExamSelected = false;
  isExamSelectedLoading = true;
  selectedExam: ICourseExamViewModel;
  isLoading = true;
  isAnswerActive: boolean[] = [];
  searchTitle = '';
  examDetail: ICourseExamDetailViewModel;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
    private courseService: CourseService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    public alertController: AlertController,
    public datepipe: DatePipe,
    private fb: FormBuilder) {

    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  ngOnInit(): void {

    this.addForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(2000)]],
      description: ['', [Validators.minLength(0), Validators.maxLength(10000)]],
      image: ['', [Validators.minLength(0), Validators.maxLength(200000)]],
      level: [0, [Validators.required, Validators.min(0), Validators.max(100)]],
      time: [10, [Validators.required, Validators.min(10), Validators.max(3600)]],
      point: [1, [Validators.required, Validators.min(1), Validators.max(100)]],
      answer1: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer2: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer3: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer4: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      trueAnswer: [1, [Validators.required, Validators.min(1), Validators.max(4)]]
    });

    this.updateForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(2000)]],
      description: ['', [Validators.minLength(0), Validators.maxLength(10000)]],
      image: ['', [Validators.minLength(0), Validators.maxLength(200000)]],
      level: [0, [Validators.required, Validators.min(0), Validators.max(100)]],
      time: [10, [Validators.required, Validators.min(10), Validators.max(3600)]],
      point: [1, [Validators.required, Validators.min(1), Validators.max(100)]],
      answer1: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer2: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer3: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      answer4: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      trueAnswer: [1, [Validators.required, Validators.min(1), Validators.max(4)]]
    });
  }

  ionViewWillEnter() {

    this.windowWidth = +window.innerWidth;
    this.isCourseSelected = false;
    let filter: ICourseFilterModel;

    this.activatedRoute.params.subscribe(params => {

      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        SharedIonic.loading(this.loadingController);

        this.isCourseSelected = false;
        this.selectedCourseId = 0;
        filter = new CourseFilterModel(false, 1, 20, this.courseSearch);

        this.courseService.GetTeacherCoursesByFilter(filter).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
              this.notfound = false;

            } else if (res.status === GResponse.NotFoundStatus) {

              this.notfound = true;
              SharedIonic.toast(this.toastController, 'دوره ای یافت نشد');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      } else {

      }

    });
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();
      event.target.complete();
    }, 2000);
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  goPage2(pageId: number | string) {
    this.setQueryParams2(+pageId);
  }

  goPage3(pageId: number | string) {
    this.setQueryParams3(+pageId);
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= +pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  setQueryParams(pageId: number) {

    SharedIonic.loading(this.loadingController);

    const page = pageId < 1 ? 1 : pageId;

    const filter = new CourseFilterModel
      (false, page, this.filteredCourses.takeEntity, this.courseSearch, this.filteredCourses.sortId);

    this.filteredCourses = filter;

    this.courseService.GetTeacherCoursesByFilter(filter).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.filteredCourses = res.data;
          this.notfound = false;

        } else if (res.status === GResponse.NotFoundStatus) {

          this.notfound = true;
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  setQueryParams2(pageId: number) {

    SharedIonic.loading(this.loadingController);

    this.examQuestionsFilter.pageId = pageId;

    this.courseService.GetExamQuestionByFilter(this.examQuestionsFilter).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.examQuestionsFilter = res.data;
          this.isLoading = false;

        } else {
          this.segmentSelected = 'Add';
          SharedIonic.toast(this.toastController, 'سوالی وجود ندارد');
        }
      },
      err => {
        this.segmentSelected = 'Add';
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  setQueryParams3(pageId: number) {

    SharedIonic.loading(this.loadingController);

    this.examsFilter.title = this.searchTitle;
    this.examsFilter.pageId = pageId;

    this.courseService.GetTeacherExamsByFilter(this.examsFilter).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.examsFilter = res.data;
          this.isExamQuestionSelected = false;
        } else {
          this.segmentSelected = 'Add';
          SharedIonic.toast(this.toastController, 'آزمونی وجود ندارد');
        }
      },
      err => {
        this.segmentSelected = 'Add';
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertAddConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      const tests: IExamQuestionTestAnswerViewModel[] = [];

      tests.push(
        new ExamQuestionTestAnswerViewModel(
          0,
          this.addForm.value.answer1,
          this.addForm.value.trueAnswer == 1 ? true : false,
          false,
          0,
          0
        )
      );

      tests.push(
        new ExamQuestionTestAnswerViewModel(
          0,
          this.addForm.value.answer2,
          this.addForm.value.trueAnswer == 2 ? true : false,
          false,
          0,
          0
        )
      );

      tests.push(
        new ExamQuestionTestAnswerViewModel(
          0,
          this.addForm.value.answer3,
          this.addForm.value.trueAnswer == 3 ? true : false,
          false,
          0,
          0
        )
      );

      tests.push(
        new ExamQuestionTestAnswerViewModel(
          0,
          this.addForm.value.answer4,
          this.addForm.value.trueAnswer == 4 ? true : false,
          false,
          0,
          0
        )
      );

      this.courseService.AddOrUpdateExamQuestion(
        new QuestionAnswerViewModel(
          new ExamQuestionViewModel(
            0,
            this.addForm.value.title,
            this.addForm.value.description,
            this.addForm.value.image,
            true,
            false,
            false,
            0,
            this.addForm.value.level,
            this.addForm.value.point,
            this.addForm.value.time,
            this.selectedCourseId
          ),
          tests
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addForm.setValue({
              title: '',
              description: '',
              image: '',
              level: 0,
              time: 10,
              point: 1,
              answer1: '',
              answer2: '',
              answer3: '',
              answer4: '',
              trueAnswer: 1,
            });
            this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  async presentAlertUpdateConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onUpdate() {

    if (this.updateForm.valid || this.selectedQuestionIndex != -1) {

      SharedIonic.loading(this.loadingController);

      const tests: IExamQuestionTestAnswerViewModel[] = [];

      for (let i = 0; i < 4; i++) {

        if (i + 1 <= this.examQuestionsFilter.questions[this.selectedQuestionIndex].tests.length) {

          switch (i) {
            case 0:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].tests[0].id,
                  this.updateForm.value.answer1,
                  this.updateForm.value.trueAnswer == 1 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 1:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].tests[1].id,
                  this.updateForm.value.answer2,
                  this.updateForm.value.trueAnswer == 2 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 2:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].tests[2].id,
                  this.updateForm.value.answer3,
                  this.updateForm.value.trueAnswer == 3 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 3:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].tests[3].id,
                  this.updateForm.value.answer4,
                  this.updateForm.value.trueAnswer == 4 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;

            default:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  '',
                  false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
          }
        } else {

          switch (i) {
            case 0:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  this.updateForm.value.answer1,
                  this.updateForm.value.trueAnswer == 1 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 1:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  this.updateForm.value.answer2,
                  this.updateForm.value.trueAnswer == 2 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 2:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  this.updateForm.value.answer3,
                  this.updateForm.value.trueAnswer == 3 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
            case 3:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  this.updateForm.value.answer4,
                  this.updateForm.value.trueAnswer == 4 ? true : false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;

            default:
              tests.push(
                new ExamQuestionTestAnswerViewModel(
                  0,
                  '',
                  false,
                  false,
                  0,
                  this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id
                )
              );
              break;
          }
        }
      }

      this.courseService.AddOrUpdateExamQuestion(
        new QuestionAnswerViewModel(
          new ExamQuestionViewModel(
            this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.id,
            this.updateForm.value.title,
            this.updateForm.value.description,
            this.updateForm.value.image,
            this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.isTest,
            false,
            this.examQuestionsFilter.questions[this.selectedQuestionIndex].question.isPlacement,
            0,
            this.updateForm.value.level,
            this.updateForm.value.point,
            this.updateForm.value.time,
            this.selectedCourseId
          ),
          tests
        )
      ).subscribe(
        res => {

          if (GResponse.SuccessStatus === res.status) {
            this.updateForm.setValue({
              title: '',
              description: '',
              image: '',
              level: '',
              time: '',
              point: '',
              answer1: '',
              answer2: '',
              answer3: '',
              answer4: '',
              trueAnswer: '',
            });
            this.selectedQuestionIndex = -1;
            this.isExamQuestionSelected = false;
            this.isLoading = true;
            this.examQuestionsFilter.pageId = 1;

            this.courseService.GetExamQuestionByFilter(this.examQuestionsFilter).subscribe(
              ress => {
                SharedIonic.dismissLoading(this.loadingController);
                if (GResponse.SuccessStatus === ress.status) {

                  this.examQuestionsFilter = ress.data;
                  this.isLoading = false;

                } else {
                  this.segmentSelected = 'Add';
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                this.segmentSelected = 'Add';
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );

            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  async presentAlertRemoveConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.DeleteExamQuestionById(this.examQuestionsFilter.questions[+index].question.id).subscribe(
      res => {
        if (GResponse.SuccessStatus === res.status) {
          this.updateForm.setValue({
            title: '',
            description: '',
            image: '',
            level: '',
            time: '',
            point: '',
            answer1: '',
            answer2: '',
            answer3: '',
            answer4: '',
            trueAnswer: '',
          });

          this.isExamQuestionSelected = false;
          SharedIonic.successToast(this.toastController);

          this.courseService.GetExamQuestionByFilter(this.examQuestionsFilter).subscribe(
            ress => {
              SharedIonic.dismissLoading(this.loadingController);
              if (GResponse.SuccessStatus === ress.status) {

                this.examQuestionsFilter = ress.data;
                this.isLoading = false;

              } else {
                this.segmentSelected = 'Add';
                SharedIonic.unSuccessToast(this.toastController);
              }
            },
            err => {
              this.segmentSelected = 'Add';
              SharedIonic.dismissLoading(this.loadingController);
              SharedIonic.unSuccessToast(this.toastController);
            }
          );
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  isUserAnswer(aIndex: number | string, qIndex: number | string): string {

    const find = this.examDetail.userTestQuestionAnswers.find(e => e.examTestQuestionAnswerId == +aIndex);

    if (find == null) {

      return 'close-outline';
    } else {
      return 'checkbox-outline';
    }
  }

  onSelectExam(index: number | string) {

    this.selectedExam = this.examsFilter.exams[index];
    this.isExamSelected = true;
    this.isExamSelectedLoading = true;

    this.courseService.GetTeacherExamById(this.selectedExam.examId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.examDetail = res.data;
          this.isExamSelectedLoading = false;
        }
        else {
          SharedIonic.toast(this.toastController, 'آزمون یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  onSelectQuestion(index: number | string) {

    this.selectedQuestionIndex = +index;

    const trueAns = this.examQuestionsFilter.questions[+index].tests.findIndex(e => e.isTrue);

    let ans1 = '';
    let ans2 = '';
    let ans3 = '';
    let ans4 = '';
    let count = 0;

    this.examQuestionsFilter.questions[+index].tests.forEach(test => {

      if (count == 0) {

        ans1 = test.answer;
      } else if (count == 1) {

        ans2 = test.answer;
      } else if (count == 2) {

        ans3 = test.answer;
      } else if (count == 3) {

        ans4 = test.answer;
      }
      count++;
      this.isAnswerActive.push(test.isActive);
    });

    this.updateForm.setValue({
      title: this.examQuestionsFilter.questions[+index].question.title,
      description: this.examQuestionsFilter.questions[+index].question.description,
      image: this.examQuestionsFilter.questions[+index].question.imageAddress,
      level: this.examQuestionsFilter.questions[+index].question.level,
      time: this.examQuestionsFilter.questions[+index].question.time,
      point: this.examQuestionsFilter.questions[+index].question.point,
      answer1: ans1,
      answer2: ans2,
      answer3: ans3,
      answer4: ans4,
      trueAnswer: trueAns + 1
    });

    this.isExamQuestionSelected = true;
  }

  segmentChanged(ev: any) {

    this.isLoading = true;

    if (this.segmentSelected == 'Update') {

      SharedIonic.loading(this.loadingController);

      this.examQuestionsFilter = new ExamQuestionFilter(this.selectedCourseId);

      this.courseService.GetExamQuestionByFilter(this.examQuestionsFilter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.examQuestionsFilter = res.data;
            this.isLoading = false;

          } else {
            this.segmentSelected = 'Add';
            SharedIonic.toast(this.toastController, 'سوالی وجود ندارد');
          }
        },
        err => {
          this.segmentSelected = 'Add';
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    } else if (this.segmentSelected == 'Exam') {

      SharedIonic.loading(this.loadingController);

      this.examsFilter = new ExamFilter(this.selectedCourseId);

      this.courseService.GetTeacherExamsByFilter(this.examsFilter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.examsFilter = res.data;
            this.isExamQuestionSelected = false;
            this.isLoading = false;
          } else {
            this.segmentSelected = 'Add';
            SharedIonic.toast(this.toastController, 'آزمونی وجود ندارد');
          }
        },
        err => {
          this.segmentSelected = 'Add';
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onSelectItem(model: ICourseModel) {

    this.selectedCourseId = +model.id;
    this.course = model;
    this.isCourseSelected = true;
  }
}
